from wandb.sdk.internal.datastore import DataStore
from wandb.proto import wandb_internal_pb2 as pb
ds = DataStore()
ds.open_for_scan('/root/autodl-tmp/importance_margin_vla_compress/wandb/offline-run-20260516_013654-3mt1egu1/run-3mt1egu1.wandb')
found = 0
last_al = last_ml = last_tl = None
for i in range(500):
    rec = ds.scan_record()
    if rec is None:
        break
    try:
        r = pb.ServerRequest()
        r.ParseFromString(rec[1])
        h = r.record_publish.record.history
        for item in h.item:
            if item.key == 'train/action_loss':
                last_al = item.value_json
            elif item.key == 'train/margin_loss':
                last_ml = item.value_json
            elif item.key == 'train/total_loss':
                last_tl = item.value_json
        if last_al:
            found += 1
    except Exception as e:
        pass
print(f'history records with action_loss: {found}')
print(f'last: al={last_al}, ml={last_ml}, tl={last_tl}')
"
